{
  "action": "tool",
  "tool": "retrieve_history",
  "args": {
    "research_concepts": [
      "offensive lineup",
      "personnel effects",
      "shot mix",
      "shot selection"
    ],
    "methodological_questions": [
      "measuring lineup impact",
      "causal inference in basketball",
      "controlling for confounding factors in lineup analysis",
      "quantifying shot mix changes"
    ],
    "query": "impact of offensive lineup changes on shot mix and shot selection, personnel effects on offensive strategy, confounding factors in NBA lineup analysis"
  }
}

{
 "research_concepts": [
  "offensive lineup",
  "personnel effects",
  "shot mix",
  "shot selection"
 ],
 "methodological_questions": [
  "measuring lineup impact",
  "causal inference in basketball",
  "controlling for confounding factors in lineup analysis",
  "quantifying shot mix changes"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-TMP-009",
   "status_as_recorded": "artifact",
   "finding": "The PULL_UP-specific decline with exposure was found to be an artifact. Without lineup fixed effects (FE), the effect shrinks from -0.0255 to -0.0063, and a placebo on other play types yields -0.0071/-0.0075, consistent with a shooter-level confound. This suggests that lineup composition (personnel) can confound results if not accounted for."
  },
  {
   "id": "FAM:SF-PAP-009",
   "status_as_recorded": "supported",
   "finding": "Lineup coverage (>=1 organizer, shaper, terminal) varies within team, is separable from talent/counts, and talent control behaves. This supports the feasibility of defining and measuring player roles within a lineup and distinguishing them from overall talent."
  },
  {
   "id": "FAM:SF34",
   "status_as_recorded": "inconclusive",
   "finding": "Offenses showed statistically significant shifts in shot mix when the opposing rim big was off the floor: DRIVE +0.82pp (SE 0.25 t=+3.3), POST_UP +0.43pp (SE 0.18 t=+2.4), and 3PA -1.79pp (SE 0.31 t=-5.8). However, the overall change in rim <=4ft percentage (+0.12pp, t=+0.4) and PPP (+0.008, t=+1.1) was small and/or inconclusive."
  },
  {
   "id": "FAM:SF-PAP-007",
   "status_as_recorded": "supported",
   "finding": "When a 'shaper' player is on the floor, teams run more CUTs (+1.353pp) and PNRs (+0.98pp) and fewer SPOT_UPs (-1.248pp) and DRIVEs (-0.542pp) within the same team-season. This demonstrates consistent within-team shifts in play-type mix based on specific player roles."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "This study described how play-type mix shifts by halftime margin, crunch time, and after runs. It did not perform inferential tests and noted the 'OTHER' play-type label was noisy."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Defensive scheme changes were deemed untestable due to reliance on inferred labels which could not reliably separate real adjustments from offensive execution differences, leading to near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF38",
   "status_as_recorded": "inconclusive",
   "finding": "This study on defensive in-game adaptation to repeated play types found an inconclusive league-wide effect, with only PULL_UP play types showing a significant within-game decline. It was limited by insufficient exposure, label errors, and low measurement reliability."
  },
  {
   "id": "FAM:SF-TMP-016",
   "status_as_recorded": "untestable",
   "finding": "Team heterogeneity in halftime play-type adaptation was untestable due to low measurement reliability; team-season slope standard deviation was similar to mean sampling error, and split-half reliability was near zero."
  },
  {
   "id": "FAM:SF-CHT-076",
   "status_as_recorded": "artifact",
   "finding": "Offensive adaptation to bonus threshold and foul-trouble bigs showed an artifactual FTA jump due to rulebook, and DRIVE increases matched a placebo. Foul-trouble big exposure was very low (1.44% of possessions) because coaches bench players."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-TMP-009",
   "what_failed": "Analyzing PULL_UP exposure-effect without lineup fixed effects",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to shooter-level confounding."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Attempting to infer defensive scheme changes from NBA matchup/PBP fields",
   "why": "A_unanswerable (question not answerable with the data or design) due to label_or_classification_error; inferred labels could not separate real defensive adjustment from offense executing differently."
  },
  {
   "id": "FAM:SF38",
   "what_failed": "Detecting league-wide defensive adaptation to repeated play types",
   "why": "LIM:insufficient_exposure, LIM:label_or_classification_error, LIM:low_measurement_reliability"
  },
  {
   "id": "FAM:SF-TMP-016",
   "what_failed": "Measuring reliable team heterogeneity in play-type adaptation",
   "why": "A_unanswerable (question not answerable with the data or design) due to low_measurement_reliability."
  },
  {
   "id": "FAM:SF-CHT-076",
   "what_failed": "Detecting offensive adaptation to bonus threshold for non-FTA outcomes and to foul-trouble bigs",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) for bonus threshold (mechanical effect); LIM:insufficient_exposure for foul-trouble bigs (coaches bench players)."
  }
 ],
 "evidence_establishes": [
  "Lineup composition (personnel) can influence observed effects on play types and shot selection, and controlling for it using fixed effects is crucial to avoid confounding (FAM:SF-TMP-009).",
  "Changes in specific player roles on the court can lead to measurable, consistent within-team shifts in play-type mix (FAM:SF-PAP-007).",
  "Offenses do adapt their shot mix based on the opponent's personnel (e.g., absence of a rim big, FAM:SF34), showing detectable shifts in specific play types like DRIVEs, POST_UPs, and 3PA.",
  "It is feasible to define and measure player roles within a lineup, and these roles are separable from overall talent (FAM:SF-PAP-009)."
 ],
 "evidence_does_not_establish": [
  "The magnitude and consistency of shot mix changes specifically due to *one's own* offensive personnel changes, as most directly relevant evidence focused on opponent's personnel or general play-type shifts.",
  "Whether offensive lineup changes have a substantial impact on overall offensive efficiency (PPP) or only on the mix of shots (FAM:SF34 found small PPP effect).",
  "Whether the available data allows for sufficiently granular and reliable labeling of shot types or play types to capture subtle changes in 'shot mix' without significant measurement error (FAM:SF-APPM-021, FAM:SF38).",
  "The specific causal pathways through which offensive personnel changes lead to shot mix changes, beyond observed correlations."
 ],
 "own_inferences": [
  "The research question is testable because previous studies have shown that both offensive player roles (FAM:SF-PAP-007) and opponent personnel (FAM:SF34) can influence play-type and shot mix, and that lineup fixed effects are important for robust analysis (FAM:SF-TMP-009).",
  "The data, including play-by-play with shot distance/result and derived play-type possessions, should be sufficient to define and measure 'shot mix' and 'offensive five' changes.",
  "The core challenge will be isolating the causal effect of offensive personnel changes from confounding factors like game state, defensive adjustments, and player-specific tendencies, which necessitates a robust fixed-effects model or similar causal inference technique."
 ],
 "uncertainties": [
  "The precise definition and measurement of 'shot mix' in the context of this question (e.g., proportions of different shot types, shot distances, play types leading to shots).",
  "The extent to which offensive personnel changes are independent of other tactical decisions or game context, which could introduce confounding.",
  "The statistical power to detect potentially subtle changes in shot mix attributable solely to offensive personnel, given the high variability in NBA possessions."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly influenced the decision to proceed and the design. Specifically, FAM:SF-TMP-009 highlighted the critical need for lineup fixed effects to control for shooter-level confounding, preventing an artifactual result. FAM:SF-PAP-007 and FAM:SF34 provided direct evidence that lineup changes (both own personnel and opponent's) can indeed shift play-type and shot mix, making the question more plausible and testable. Without this evidence, the risk of confounding might have led to a 'do_not_proceed' decision or a less robust design."
 },
 "testability": {
  "p_testable": 0.8,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-PAP-007",
   "FAM:SF34",
   "FAM:SF-TMP-009"
  ],
  "summary": "Previous work has established that lineup composition and specific player roles can significantly influence play-type mix and that opponent personnel changes can alter shot mix (FAM:SF-PAP-007, FAM:SF34). It also underscored the importance of controlling for lineup effects to avoid confounding (FAM:SF-TMP-009). However, no single study directly and comprehensively answers whether *one's own* offensive five changes *itself* move shot mix in a general sense, thus demonstrating the design can detect personnel effects."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Changes in the offensive five are not random. They are driven by game state, opponent defense, foul trouble, rest, and coaching decisions, all of which can independently affect shot mix. A naive comparison would be highly confounded."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The 'shot mix' must be reliably measured. While shot distance and result are direct, relying on derived 'play-type possession records' might introduce measurement reliability issues if the play-type classification is noisy (as seen in FAM:SF-APPM-021 and FAM:SF38 for 'OTHER' play types)."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While 3 seasons of NBA data are substantial, specific lineup combinations might have limited minutes together, making it challenging to detect subtle shifts in shot mix with sufficient power, especially for less common lineups. FAM:SF34 noted small effects on overall PPP and rim percentage, despite significant shifts in some play types."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Some specific personnel changes or lineup types might occur infrequently, leading to sparse data for certain comparisons, similar to the foul-trouble big exposure issue in FAM:SF-CHT-076."
  }
 ],
 "predicted_outcome": {
  "supported": 0.5,
  "rejected": 0.2,
  "untestable": 0.1,
  "artifact": 0.1,
  "uncertain": 0.1
 },
 "decision": "proceed",
 "design": {
  "estimand": "The causal effect of a change in the offensive five's personnel composition on the team's subsequent shot mix (distribution of shot types, shot distances, and associated play types) within the same game, controlling for confounding factors.",
  "unit": "Offensive possession.",
  "sample": "All offensive possessions from NBA 2022-23, 2023-24, and 2024-25 regular seasons and playoffs. Focus on possessions immediately following a substitution that changes the offensive five, comparing the shot mix of the new lineup to the previous lineup, or to a counterfactual where no change occurred.",
  "power": "Sufficient power to detect a change in the proportion of at least one major shot type (e.g., 3PA, DRIVE, POST_UP) by 0.5 percentage points or more with 80% power at alpha=0.05. Power analysis will be conducted using observed variance of shot mix components. The sample size of 3 seasons (1.07M possessions in FAM:SF34) should provide adequate power for common lineup changes.",
  "controls": "Use a fixed-effects model at the team-game-lineup level to control for unobserved heterogeneity, including game state, opponent defense, coaching strategy, and player-specific tendencies (as highlighted by FAM:SF-TMP-009). Include fixed effects for: offensive team, defensive team, game ID, period, score differential, time remaining, and previous offensive play type. Consider player-level fixed effects for individual players to isolate the 'lineup effect' beyond individual player tendencies. Compare 'on-court' vs 'off-court' metrics for specific player types (e.g., shaper, rim big) as a robustness check.",
  "falsification": "Implement a placebo test by constructing 'fake' lineup changes that are not real substitutions but occur at similar frequencies and game contexts, and verify that these placebo changes do not significantly affect shot mix. Also, test for effects on defensive metrics, which should not be directly impacted by offensive personnel changes.",
  "multiplicity": "Adjust for multiple comparisons if examining changes across many distinct shot mix components (e.g., different shot types, shot zones, or play types) using methods like Holm-Bonferroni correction or by focusing on a predefined primary outcome (e.g., overall 3PA%).",
  "decision_rule": "The hypothesis is supported if there is a statistically significant (p < 0.05, two-tailed, after multiplicity correction) and practically meaningful change (e.g., >0.5pp for major shot types) in at least one key component of shot mix attributable to offensive personnel changes, as identified by the fixed-effects model, and if placebo tests do not show similar effects.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs. Per-game files from NBA stats API: play-by-play, substitution rotation intervals, starters, defensive matchup minutes and partial possessions, box-score summary. Derived play-type possession records."
 }

